import { test, expect } from '@playwright/test';

test.describe('Font Size Readability on Small Screens', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.setViewportSize({ width: 375, height: 667 });
  });

  test('should display readable font size for main heading on small screen', async ({ page }) => {
    const heading = page.getByRole('heading', { level: 1 });
    const fontSize = await heading.evaluate((el) => {
      return window.getComputedStyle(el).fontSize;
    });

    const fontSizeValue = parseFloat(fontSize);
    expect(fontSizeValue).toBeGreaterThanOrEqual(16);
  });

  test('should display readable font size for body text on small screen', async ({ page }) => {
    const bodyText = page.getByText(/content|text|paragraph/i).first();
    const fontSize = await bodyText.evaluate((el) => {
      return window.getComputedStyle(el).fontSize;
    });

    const fontSizeValue = parseFloat(fontSize);
    expect(fontSizeValue).toBeGreaterThanOrEqual(14);
  });

  test('should not require zoom to read text on small screen', async ({ page }) => {
    const mainContent = page.getByRole('main');
    const isVisible = await mainContent.isVisible();
    expect(isVisible).toBe(true);

    const boundingBox = await mainContent.boundingBox();
    expect(boundingBox).not.toBeNull();
    if (boundingBox) {
      expect(boundingBox.width).toBeLessThanOrEqual(375);
    }
  });

  test('should maintain readable line height on small screen', async ({ page }) => {
    const paragraph = page.getByRole('paragraph').first();
    const lineHeight = await paragraph.evaluate((el) => {
      return window.getComputedStyle(el).lineHeight;
    });

    const lineHeightValue = parseFloat(lineHeight);
    expect(lineHeightValue).toBeGreaterThanOrEqual(16);
  });
});
